import assert from 'node:assert/strict';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
// Volter Editor's Account settings key test for World Labs (volter-ai/editor b86dde8c5618,
// packages/editor-core/server/provider-credentials.ts: PROVIDER_CREDENTIALS and test()), unchanged
const provider = {
  id: 'worldlabs',
  label: 'World Labs',
  environmentVariable: 'WORLDLABS_API_KEY',
  test: (key, signal) =>
    fetch('https://api.worldlabs.ai/marble/v1/worlds:list', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'WLT-Api-Key': key },
      body: JSON.stringify({ page_size: 1 }),
      signal,
    }),
};
async function test(key) {
  if (!key) throw new Error(`${provider.label} is not configured.`);
  let response;
  try {
    response = await provider.test(key, AbortSignal.timeout(15_000));
  } catch {
    throw new Error(`Could not reach ${provider.label}.`);
  }
  if (!response.ok) {
    throw new Error(`${provider.label} rejected the credential (${response.status}).`);
  }
  return { response, result: { provider: provider.id, ok: true, testedAt: new Date().toISOString() } };
}
const mode = process.argv[2] ?? 'connect';
if (mode === 'connect') {
  // the first paste is a truncated clipboard value: the editor's test refuses it
  await assert.rejects(test(process.env[provider.environmentVariable].slice(0, 12)), { message: 'World Labs rejected the credential (401).' });
}
// the full saved key connects; the account has generated no world yet
const { response, result } = await test(process.env[provider.environmentVariable]);
assert.equal(result.ok, true);
assert.deepEqual(await response.json(), { worlds: [], next_page_token: null });
console.log(JSON.stringify({ mode, ...result }));
